-- Xác định kiểu dữ liệu nhờ website https://convertcsv.com/csv-to-sql.htm
USE `da2_job_data_db`;

CREATE TABLE IF NOT EXISTS `raw_data` (
`id` INT AUTO_INCREMENT PRIMARY KEY,
`job_url`       VARCHAR(250) NOT NULL,
`job_title`     VARCHAR(250),
`company_name`  VARCHAR(200),
`location`      VARCHAR(200),
`date_posted`   DATE,
`date_deadline` DATE,
`source`        VARCHAR(20) NOT NULL,
`work_type`     VARCHAR(20),
`job_position`  VARCHAR(50),
`edu`           VARCHAR(20),
`job_industry`  VARCHAR(50),
`related_data_analyst_bi`   BOOLEAN NOT NULL,
`related_data_engineer`     BOOLEAN NOT NULL,
`related_data_science`      BOOLEAN NOT NULL,
`related_ai_ml`             BOOLEAN NOT NULL,
`mean_salary_fix`           NUMERIC(18,9),   -- Kiểu số chính xác cố định - Exact Numeric
`min_experience_fix`        NUMERIC(4,1),    -- còn DOUBLE dễ gây sai số vì làm tròn.
`req_sql`                   BOOLEAN NOT NULL,
`req_python`                BOOLEAN NOT NULL,
`req_excel`                 BOOLEAN NOT NULL,
`req_cloud_mordern_stack`   BOOLEAN NOT NULL,
`req_big_data`              BOOLEAN NOT NULL,
`req_other_programming`     BOOLEAN NOT NULL,
`req_ai_ml`                 BOOLEAN NOT NULL,
`req_devops`                BOOLEAN NOT NULL,
`req_bi_viz`                BOOLEAN NOT NULL,
`req_english`               BOOLEAN NOT NULL,
`financial_benefits`        BOOLEAN NOT NULL,
`health_benefits`           BOOLEAN NOT NULL,
`training_growth_benefits`  BOOLEAN NOT NULL,
`culture_benefits`          BOOLEAN NOT NULL,
`exp_range` VARCHAR(20)
);
TRUNCATE TABLE `raw_data`;
